/*
 * Pro tips
 * - After sorting, compare two candidates: the largest three, or the smallest two times the largest.
 * - Two large-magnitude negatives can beat three positive values; do not ignore the low end.
 * - Assumes at least three elements. Check all-negative values, zeros, and exactly three values.
 * - This sorts the input in place. Products use int; cast before multiplication and use long if the range requires it.
 * - Complexity: O(n log n) time; Java list sorting may use O(n) space. Tracking five extremes gives an O(n)-time alternative.
 */

import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

class Solution {
    public static int maxProductOfThree(List<Integer> nums) {
        nums.sort(null);

        int n = nums.size();
        int product1 = nums.get(n - 1) * nums.get(n - 2) * nums.get(n - 3);
        int product2 = nums.get(0) * nums.get(1) * nums.get(n - 1);
        int result = product2;
        if (product1 > result) {
            result = product1;
        }
        return result;
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        List<Integer> nums = splitWords(scanner.nextLine()).stream().map(Integer::parseInt).collect(Collectors.toList());
        scanner.close();
        int res = maxProductOfThree(nums);
        System.out.println(res);
    }
}
